// Lab: Namibia jobs map (field: data). Standalone page at /lab/namibia-jobs/, generated by scripts/build.mjs.
// Every number on the page is read from labs/namibia-jobs.json, which scripts/lab-data/build-namibia.mjs writes from the validated CSV.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

function loadData() {
  const r = spawnSync(process.execPath, [path.join(ROOT, 'scripts', 'lab-data', 'build-namibia.mjs')], { encoding: 'utf8' });
  if (r.status !== 0) throw new Error('namibia-jobs: the CSV did not validate\n' + r.stderr);
  return JSON.parse(fs.readFileSync(path.join(ROOT, 'labs', 'namibia-jobs.json'), 'utf8'));
}

const pct = (v) => (Math.round(v * 10) / 10).toFixed(1);
const num = (n) => n.toLocaleString('en-US');

export default {
  slug: 'namibia-jobs',
  field: 'data',
  title: 'Namibia jobs map',
  blurb: 'Unemployment across Namibia\'s 14 regions as a radar chart, ranked dots, a slope chart and a tile map, transcribed from the Namibia Statistics Agency\'s own reports.',
  personas: ['data'],

  page({ esc }) {
    const data = loadData();
    const byId = Object.fromEntries(data.series.map((s) => [s.id, s]));
    const all23 = byId['2023-overall-19th-icls'], youth23 = byId['2023-youth-19th-icls'];
    const regions = data.regions;
    const rate = (s, r) => s.values[r].value;
    const ranked = [...regions].sort((a, b) => rate(all23, b) - rate(all23, a));
    const top = ranked[0], bottom = ranked[ranked.length - 1];
    const youthHigherEverywhere = regions.every((r) => rate(youth23, r) > rate(all23, r));
    const nat = (s) => s.values[data.national];

    const situation = `Unemployment in Namibia is high, and it is far from even. In the 2023 census, ${pct(rate(all23, top))}% of the labour force in ${esc(top)} was without work, against ${pct(rate(all23, bottom))}% in ${esc(bottom)}; the national rate was ${pct(nat(all23).value)}%. `
      + `Young people (15 to 34) had it harder still, at ${pct(nat(youth23).value)}% nationally. The tempting next step is to set 2023 beside the 2018 Labour Force Survey and call the gap a trend. `
      + `But the two count unemployment differently: the 2018 headline rate also counts people who were available for work but had not looked for it, while the census counts only people who searched and were available, and the Statistics Agency itself warns that survey and census results cannot be directly compared. `
      + `This lab puts the published regional numbers side by side, keeps each definition visible, and lets you choose which comparisons to look at.`;

    const look = [
      `Start on the radar with the two 2023 series switched on (both from the census, same definition). ${youthHigherEverywhere ? 'The youth shape sits outside the all-ages shape on every one of the 14 axes. ' : ''}Hover a spoke, or tab to the chart and use the arrow keys, to read exact values, counts and the table and page they came from.`,
      'Switch on a 2018 series. A note appears saying what that comparison can and cannot tell you. Then try the slope chart, which sets 2018 and 2023 side by side without calling the difference a change.',
      'Open the tile map and the ranked dots to see the same numbers as geography and as a ranking, then open &ldquo;Show the data as a table&rdquo; for every figure with its source row.',
    ];

    const seriesLabel = (s) => `${s.year} ${s.measure === 'youth' ? 'youth 15 to 34' : 'all 15+'} (${s.definition === '19th-icls' ? 'census, 19th ICLS' : s.definition})`;

    const rows = [data.national, ...regions].map((r) => `
          <tr><th scope="row">${esc(r)}</th>${data.series.map((s) => `<td class="num">${pct(s.values[r].value)}</td>`).join('')}</tr>`).join('');
    const sources = data.series.map((s) => `
          <tr><th scope="row">${esc(seriesLabel(s))}</th><td>${esc(s.publication)}</td><td>${esc(s.table)}</td><td class="num">${esc(s.page_printed)} (PDF ${esc(s.page_pdf)})</td><td>${esc(s.retrieved)}</td></tr>`).join('');

    const demo = `
      <p><span class="lab-badge">Not an official statistic</span> <span class="lab-note">Figures transcribed from the Namibia Statistics Agency (NSA) reports named under &ldquo;Limits and sources&rdquo;. Shares are percentages of the labour force.</span></p>
      <div class="nj-app" id="nj-app" data-src="/labs/namibia-jobs.json">
        <p class="lab-note nj-loading">Loading the chart. It needs JavaScript; the table below has every figure without it.</p>
      </div>
      <div class="nj-defs">
        <h3>What changed between 2018 and 2023</h3>
        <dl>
          <dt>Broad (2018 survey, headline)</dt><dd>Counts people who are not in employment and are available for work, without requiring that they actively looked for work in the past week.</dd>
          <dt>Strict (2018 survey, Annex A)</dt><dd>Counts only people who searched for work and were available. The 2018 report gives this for international comparison.</dd>
          <dt>19th ICLS (2023 census)</dt><dd>Counts people who were not employed, carried out job search activities and were available to take a job.</dd>
        </dl>
      </div>
      <details class="nj-table" id="nj-table">
        <summary>Show the data as a table</summary>
        <div class="nj-scroll">
          <table class="lab-table">
            <caption>Unemployment rate (%) by region, every series</caption>
            <thead><tr><th scope="col">Region</th>${data.series.map((s) => `<th scope="col" class="num">${esc(seriesLabel(s))}</th>`).join('')}</tr></thead>
            <tbody>${rows}
            </tbody>
          </table>
        </div>
        <div class="nj-scroll">
          <table class="lab-table">
            <caption>Source row for each series</caption>
            <thead><tr><th scope="col">Series</th><th scope="col">Publication</th><th scope="col">Table</th><th scope="col" class="num">Page</th><th scope="col">Retrieved</th></tr></thead>
            <tbody>${sources}
            </tbody>
          </table>
        </div>
        <p class="lab-note">Counts of unemployed people and labour force sit in the JSON the charts read, <a class="inline-link" href="/labs/namibia-jobs.json">labs/namibia-jobs.json</a>.</p>
      </details>`;

    const built = `
      <p>The data starts as a CSV, <code>scripts/lab-data/namibia-labour.csv</code>: ${data.series.length * (regions.length + 1)} rows, one per region (and one for Namibia) per series, each carrying the publication, table number, printed and PDF page, the PDF address and the date it was retrieved. The numbers were transcribed from the tables in the two NSA PDFs, then every count was checked against the page its row cites.</p>
      <p>A validator, <code>scripts/lab-data/build-namibia.mjs</code>, runs on every site build. It rejects blank cells, unknown regions, a missing region in any series, duplicates, and any rate that does not match unemployed divided by labour force to within rounding. It caught a deliberately mistyped Omusati figure in testing. If it passes, it writes the JSON the page loads; if not, the build stops.</p>
      <p>The charts are hand-written SVG drawn by one vanilla JavaScript file, with no chart or map library and no request to anything but this site. All four views use the same fixed scale (0 to 70%) or the same fixed colour bins, so a small shape means a small rate rather than an auto-zoomed axis. Each series has its own colour, line pattern and marker shape, so colour is never the only cue. The tile map places one square per region roughly where it sits on the map; positions are approximate and areas are not to scale.</p>
      <p>Accessibility: the table above is the full equivalent of every chart and works without JavaScript; the chart regions can be reached by keyboard (arrow keys, Home and End) and announce their values; controls are real buttons with pressed state; nothing animates when the system asks for reduced motion; and it fits a 390 pixel wide screen without sideways scrolling.</p>`;

    const limits = `
      <p><strong>Not an official statistic.</strong> This is a personal proof of concept that redraws published numbers. For decisions, use the NSA publications.</p>
      <p>Sources (primary documents only; no press report is used, because press coverage of the same numbers disagrees with itself and with the reports):</p>
      <ul>
        <li><em>The Namibia Labour Force Survey 2018 Report</em>, Namibia Statistics Agency, from its <a class="inline-link" href="${esc(byId['2018-overall-broad'].source_url)}" rel="noopener">microdata archive</a>. Broad rate by region: Table 5.3, page 63. Strict rate by region: Annex A, Table A.2, page 75. Youth (15 to 34) rate by region: Table 6.5, page 71. Retrieved ${esc(byId['2018-overall-broad'].retrieved)}.</li>
        <li><em>2023 Population and Housing Census Labour Force Report</em>, Namibia Statistics Agency, from <a class="inline-link" href="${esc(all23.source_url)}" rel="noopener">nsa.org.na</a>. Rate by region: Table 5.1, printed page 39 (PDF page 51). Youth (15 to 34) rate by region: Table 6.7, printed page 51 (PDF page 63). The caution that survey and census results cannot be directly compared is on printed page 3 (PDF page 15); the 2018 and 2023 national rates appear side by side in Figure 5.1, printed page 38. Retrieved ${esc(all23.retrieved)}.</li>
      </ul>
      <p>What the data does and does not support:</p>
      <ul>
        <li>The 2018 survey and the 2023 census differ in definition, instrument and coverage. Every 2018 against 2023 view is labelled as a side-by-side, not a measured change. The two 2023 series are the only pair that shares source and definition.</li>
        <li>The 2023 report contradicts itself on youth: its summary text (PDF page 11) says 44.1% for 2023, while its own Table 6.7 and Table 0.1 say ${pct(nat(youth23).value)}%, which is what ${num(nat(youth23).unemployed)} divided by ${num(nat(youth23).labour_force)} gives. The lab uses the table. Press reports quote both numbers.</li>
        <li>The 2018 report gives a strict youth rate by region only for ages 15 to 24 (Annex B, Table B.3), a different age band, so it is left out. No strict-definition youth series is shown.</li>
        <li>The 2018 survey is a sample, and its regional estimates carry sampling error (the report prints precision measures in Annex D). The charts do not draw error bars, so small gaps between regions should not be over-read.</li>
        <li>Names and numbering: the 2018 report writes <em>!Karas</em> where the 2023 report writes <em>//Kharas</em>; the lab uses the second. The 2018 contents list calls the regional table 5.2, while the table in the body is numbered 5.3; the lab cites the body. 2018 Zambezi is printed as 37.68 and shown as 37.7.</li>
        <li>Rates are shares of the labour force, not of the whole population, and nothing here covers wages, informal work or people outside the labour force.</li>
      </ul>`;

    return { situation, look, demo, built, limits, scripts: ['/labs/namibia-jobs.js'], css: ['/labs/namibia-jobs.css'] };
  },
};
